sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?director ?birthPlace WHERE {
  dbr:Bollywood_Calling dbo:director ?director .
  OPTIONAL { ?director dbp:birthPlace ?bp . }
  OPTIONAL { ?director dbo:birthPlace ?bp2 . }
  BIND (COALESCE(?bp, ?bp2) AS ?birthPlace)
}
LIMIT 100

